import numpy as np
rng = np.random.default_rng(0)

def conv_naive(x, w, b, s=1, p=0):        # x:(N,Cin,H,W) w:(Cout,Cin,K,K) b:(Cout,)
    N, C, H, W = x.shape; F, _, K, _ = w.shape
    x = np.pad(x, ((0, 0), (0, 0), (p, p), (p, p)))
    H2, W2 = (H - K + 2*p)//s + 1, (W - K + 2*p)//s + 1
    out = np.zeros((N, F, H2, W2))
    for n in range(N):
        for f in range(F):
            for i in range(H2):
                for j in range(W2):
                    patch = x[n, :, i*s:i*s+K, j*s:j*s+K]
                    out[n, f, i, j] = np.sum(patch * w[f]) + b[f]
    return out

def conv_im2col(x, w, b, s=1, p=0):
    N, C, H, W = x.shape; F, _, K, _ = w.shape
    x = np.pad(x, ((0, 0), (0, 0), (p, p), (p, p)))
    H2, W2 = (H - K + 2*p)//s + 1, (W - K + 2*p)//s + 1
    cols = np.stack([x[:, :, i*s:i*s+K, j*s:j*s+K].reshape(N, -1)
                     for i in range(H2) for j in range(W2)], axis=2)  # (N, C*K*K, H2*W2)
    out = w.reshape(F, -1) @ cols + b[:, None]                        # 행렬 곱 한 번
    return out.reshape(N, F, H2, W2)

x = rng.standard_normal((2, 3, 7, 7)); w = rng.standard_normal((4, 3, 3, 3)); b = rng.standard_normal(4)
for s, p in [(1, 0), (1, 1), (2, 1)]:
    a, c = conv_naive(x, w, b, s, p), conv_im2col(x, w, b, s, p)
    print(f"s={s} p={p} shape={a.shape} max|diff|={np.abs(a - c).max():.1e}")
